    const star = (a, b, c, al, s = 2) => { R(a - s, b, s * 2 + 1, 1, c, al); R(a, b - s, 1, s * 2 + 1, c, al); R(a - 1, b - 1, 3, 3, '#fff', al); };
    const ring = (ox, oy, rx, ry, n, c, al, ph = 0, s = 2) => { for (let i = 0; i < n; i++){ const a = i * 2 * PI / n + ph; R(ox + K(a) * rx, oy + S(a) * ry, s, s, c, al); } };
